s.orderType = 'lab'
s.activeSection = null
s.searchText = ''
s.currentGroups = []
s.currentCrossGroups = []
s.selected = {}
s.gttMinutes = {}
s.customValues = {}
s.useWithdrawPrice = false
s.labGroupsByKey = {}
s.labLoading = true


s.sectionNameFor = (code) => {
  const found = (s.sections[s.orderType] || []).find((row) => row.code === code)
  return found ? found.name : code
}
s.baseGroupsFor = (sectionCode) => {
  const groups = s.labGroupsByKey[sectionCode] || []
  const sectionName = s.sectionNameFor(sectionCode)
  return groups.map((g) => ({ ...g, sectionCode, sectionName }))
}
s.baseGroups = () => s.baseGroupsFor(s.activeSection)
s.crossSectionMatches = () => {
  const q = (s.searchText || '').trim().toLowerCase()
  if (!q) return []
  const others = (s.sections[s.orderType] || []).filter((sec) => sec.code !== s.activeSection)
  const out = []
  others.forEach((sec) => {
    s.baseGroupsFor(sec.code).forEach((group) => {
      const items = group.items.filter((item) =>
        (item.code || '').toLowerCase().includes(q) ||
        item.name.toLowerCase().includes(q) ||
        group.name.toLowerCase().includes(q)
      )
      if (items.length > 0) out.push({ ...group, id: 'cross-' + sec.code + '-' + group.id, items })
    })
  })
  return out
}

s.buildGroups = () => {
  const base = s.baseGroups()
  const q = (s.searchText || '').trim().toLowerCase()
  s.currentGroups = !q ? base : base
    .map((group) => ({ ...group, items: group.items.filter((item) =>
      (item.code || '').toLowerCase().includes(q) ||
      item.name.toLowerCase().includes(q) ||
      group.name.toLowerCase().includes(q)
    ) }))
    .filter((group) => group.items.length > 0)
  s.currentCrossGroups = q ? s.crossSectionMatches() : []
}

s.selectSection = (code) => { s.activeSection = code; s.searchText = ''; s.buildGroups() }

s.onSearchInput = (value) => { s.searchText = value || ''; s.buildGroups() }
s.currentSectionName = () => {
  const found = (s.sections[s.orderType] || []).find((row) => row.code === s.activeSection)
  return found ? found.name : s.activeSection
}

const flattenSelectedGroups = (raw) => {
  if (!raw) return []
  let groups = []
  try { groups = JSON.parse(raw) || [] } catch (e) { return [] }
  if (!Array.isArray(groups)) return []
  const out = []
  groups.forEach((g) => {
    const items = (g && Array.isArray(g.selected_items)) ? g.selected_items : []
    items.forEach((item) => out.push(item))
  })
  return out
}
const groupRowsBySection = (rows) => {
  const order = []
  const bySection = {}
  rows.forEach((row) => {
    const key = (row.sectionCode || 'UNSPECIFIED') + '|' + (row.sectionName || 'อื่นๆ')
    if (!bySection[key]) { bySection[key] = { section_code: row.sectionCode || null, section_name: row.sectionName || 'อื่นๆ', selected_items: [], specimenOrder: [], specimenByCode: {} }; order.push(key) }
    bySection[key].selected_items.push(row)
    const spec = row.c_specimen
    if (spec && spec.specimen_code && !bySection[key].specimenByCode[spec.specimen_code]) {
      bySection[key].specimenByCode[spec.specimen_code] = spec
      bySection[key].specimenOrder.push(spec.specimen_code)
    }
  })
  return order.map((key) => {
    const g = bySection[key]
    const sectionMeta = (s.sections.lab || []).find((sec) => sec.code === g.section_code)
    return {
      section_code: g.section_code,
      section_name: g.section_name,
      unit: sectionMeta ? sectionMeta.unit : null,
      selected_items: g.selected_items,
      specimens: g.specimenOrder.map((code) => {
        const rec = s.specimenRecordFor(g.section_code, code)
        return { ...g.specimenByCode[code], storage: rec ? rec.storage : 'ส่งทันที', source: rec ? rec.source : null }
      })
    }
  })
}
s.foreignRows = () => {
  const raw = field.formModel && field.formModel.selected_items_json
  return flattenSelectedGroups(raw).filter((row) => row.orderType !== s.orderType)
}
s.reconcileFromField = () => {
  const raw = field.formModel && field.formModel.selected_items_json
  if (!raw) return
  const rows = flattenSelectedGroups(raw)
  const ownIds = new Set(rows.filter((row) => row.orderType === s.orderType).map((row) => row.id))
  Object.keys(s.selected).forEach((id) => { if (!ownIds.has(id)) delete s.selected[id] })
}
s.isGroupChecked = (group) => group.items.length > 0 && group.items.every((item) => !!s.selected[item.id])
s.isGroupIndeterminate = (group) => !s.isGroupChecked(group) && group.items.some((item) => !!s.selected[item.id])
s.isItemChecked = (item) => !!s.selected[item.id]
s.toggleGroup = (group) => {
  s.reconcileFromField()
  const uncheck = s.isGroupChecked(group)
  const sectionCode = group.sectionCode || s.activeSection
  const sectionName = group.sectionName || s.currentSectionName()
  group.items.forEach((item) => {
    if (uncheck) delete s.selected[item.id]
    else s.selected[item.id] = { ...item, groupName: group.name, orderType: s.orderType, sectionCode, sectionName }
  })
  s.syncSelectedField()
}
s.toggleItem = (item, group) => {
  s.reconcileFromField()
  if (s.selected[item.id]) delete s.selected[item.id]
  else s.selected[item.id] = { ...item, groupName: group.name, orderType: s.orderType, sectionCode: group.sectionCode || s.activeSection, sectionName: group.sectionName || s.currentSectionName() }
  s.syncSelectedField()
}

s.specimenRecords = []
s.selectedList = () => { s.reconcileFromField(); return Object.values(s.selected).concat(s.foreignRows()) }
s.selectedCount = () => s.selectedList().length
s.effectivePrice = (item) => Number(s.useWithdrawPrice ? item.withdraw_price : item.sale_price) || 0
s.selectedTotal = () => s.selectedList().reduce((sum, item) => sum + s.effectivePrice(item), 0)
s.selectedBySection = () => {
  const order = []
  const bySection = {}
  s.selectedList().forEach((row) => {
    const key = row.sectionName || 'อื่นๆ'
    if (!bySection[key]) { bySection[key] = { sectionName: key, rows: [] }; order.push(key) }
    bySection[key].rows.push(row)
  })
  return order.map((key) => {
    const rows = bySection[key].rows
    const subtotal = rows.reduce((sum, row) => sum + s.effectivePrice(row), 0)
    const sectionCode = rows.length ? rows[0].sectionCode : null
    const specimenOrder = []
    const specimenByCode = {}
    rows.forEach((row) => {
      const spec = row.c_specimen
      if (!spec || !spec.specimen_code) return
      if (!specimenByCode[spec.specimen_code]) { specimenByCode[spec.specimen_code] = { specimen_code: spec.specimen_code, label: spec.label }; specimenOrder.push(spec.specimen_code) }
    })
    const specimens = specimenOrder.map((code) => specimenByCode[code])
    return { sectionName: key, sectionCode, rows, subtotal, specimens }
  })
}
s.money = (value) => Number(value || 0).toLocaleString('th-TH', { minimumFractionDigits: 2, maximumFractionDigits: 2 })
s.isGttTimeItem = (item) => ['C35','C352','C353','C354','C355','C356','C357','C358','C359','C3510','C3511','C3512'].includes(item.code)
s.gttMinute = (item) => s.gttMinutes[item.id] || ''
s.customValue = (item) => s.customValues[item.id] || ''
s.setCustomValue = (item, group, value) => {
  s.reconcileFromField()
  const text = String(value == null ? '' : value).slice(0, 200)
  s.customValues = { ...s.customValues, [item.id]: text }
  if (text && !s.selected[item.id]) s.selected[item.id] = { ...item, groupName: group.name, orderType: s.orderType, sectionCode: group.sectionCode || s.activeSection, sectionName: group.sectionName || s.currentSectionName() }
  if (!text && s.selected[item.id]) delete s.selected[item.id]
  s.syncSelectedField()
}
s.setGttMinute = (item, group, value) => {
  s.reconcileFromField()
  const minute = String(value == null ? '' : value).replace(/\D/g, '').slice(0, 4)
  s.gttMinutes = { ...s.gttMinutes, [item.id]: minute }
  if (!s.selected[item.id]) s.selected[item.id] = { ...item, groupName: group.name, orderType: s.orderType, sectionCode: group.sectionCode || s.activeSection, sectionName: group.sectionName || s.currentSectionName() }
  s.syncSelectedField()
}
s.removeSelected = (id) => {
  delete s.selected[id]
  if (s.gttMinutes[id] !== undefined) { const next = { ...s.gttMinutes }; delete next[id]; s.gttMinutes = next }
  if (s.customValues[id] !== undefined) { const nextCustom = { ...s.customValues }; delete nextCustom[id]; s.customValues = nextCustom }
  s.syncSelectedField(id)
}
s.resetOrder = () => { s.selected = {}; s.gttMinutes = {}; s.customValues = {}; s.syncSelectedField() }
s.setUseWithdrawPrice = (enabled) => { s.useWithdrawPrice = enabled === true; s.syncSelectedField() }

s.syncSelectedField = (excludeId) => {
  const form = field.getFormRef()
  if (!form) return
  const priceMode = s.useWithdrawPrice ? 'withdraw' : 'sale'
  const ownRows = Object.values(s.selected).map((item) => ({
    ...item,
    sale_price: Number(item.sale_price) || 0,
    withdraw_price: Number(item.withdraw_price) || 0,
    effective_price: s.effectivePrice(item),
    price_mode: priceMode,
    gtt_minute: s.isGttTimeItem(item) ? (s.gttMinutes[item.id] || '') : null,
    custom_text: item.is_custom ? (s.customValues[item.id] || '') : null
  }))
