  const seen = {}
  rows.forEach((row) => {
    const spec = row.c_specimen
    if (!spec || !spec.specimen_code) return
    const sectionCode = row.sectionCode
    const key = sectionCode + '|' + spec.specimen_code
    if (seen[key]) return
    seen[key] = true
    const prev = prevByKey[key]
    next.push({
      section_code: sectionCode,
      specimen_code: spec.specimen_code,
      storage: prev ? prev.storage : 'ส่งทันที',
      source: prev ? prev.source : null
    })
  })
  s.specimenRecords = next
}
