s.loadLabCatalog = () => {
  const makeSectionResolver = (sectionByRefCode, sectionByCode) => (secRef) => {
    if (secRef && typeof secRef === 'object' && secRef.section_code != null) {
      return { code: String(secRef.section_code), name: secRef.section_name || secRef.label || 'ไม่ระบุหมวด', unit: secRef.unit || null }
    }
    if (typeof secRef === 'string' || typeof secRef === 'number') {
      const raw = String(secRef).trim()
      const byRefCode = sectionByRefCode[raw]
      if (byRefCode) return { code: String(byRefCode.ref_code), name: byRefCode.name, unit: byRefCode.unit || null }
      const byCode = sectionByCode[raw.toUpperCase()]
      if (byCode) return { code: String(byCode.ref_code), name: byCode.name, unit: byCode.unit || null }
    }
    return { code: 'UNSPECIFIED', name: 'ไม่ระบุหมวด', unit: null }
  }
  const makeSpecimenResolver = (specimenByCode) => (specRef) => {
    if (specRef && typeof specRef === 'object' && specRef.specimen_code != null) {
      return specRef
    }
    if (typeof specRef === 'string' && specRef.trim()) {
      const match = specimenByCode[specRef.trim().toUpperCase()]
      if (match) {
        return { value: match._id, label: match.name, specimen_code: match.code, specimen_name: match.name }
      }
    }
    return null
  }
  const loadItems = (resolveSectionInfo, resolveSpecimenInfo) => {
    field.getFormRef().userState.crudGetAll({
      sdProvider: { providerId: '6a7c7c2974a0be190cc303e0', providerType: 'FORM', options: { limit: 5000 } },
      totalEnable: true
    }, (res) => {
      const rows = (res && res.data) || []
      const sectionsByCode = {}
      const groupsByListKey = {}
      rows.forEach((row) => {
        const secRef = row.section_id
        const resolved = resolveSectionInfo(secRef)
        const sectionCode = resolved.code
        const sectionName = resolved.name
        if (!sectionsByCode[sectionCode]) sectionsByCode[sectionCode] = { code: sectionCode, name: sectionName, unit: resolved.unit || null }
        const groupName = (row.item_group || '').trim() || 'อื่นๆ'
        const listKey = sectionCode + '|' + groupName
        if (!groupsByListKey[listKey]) groupsByListKey[listKey] = { id: 'lab-' + sectionCode + '-' + groupName, name: groupName, sectionCode, items: [] }
        groupsByListKey[listKey].items.push({
          id: 'lab-' + sectionCode + '-' + (row._id || row.item_code),
          master_id: row._id,
          code: row.item_code,
          item_code: row.item_code,
          name: row.item_name,
          master_item_name: row.item_name,
          section_name: sectionName,
          sale_price: Number(row.sale_price) || 0,
          withdraw_price: Number(row.withdraw_price) || 0,
          price: Number(row.sale_price) || 0,
          data_source: 'real',
          c_specimen: resolveSpecimenInfo(row.c_specimen)
        })
      })
      const sections = Object.values(sectionsByCode).sort((a, b) => a.name.localeCompare(b.name, 'th'))
      const groupsByKey = {}
      Object.keys(groupsByListKey).forEach((key) => {
        const g = groupsByListKey[key]
        if (!groupsByKey[g.sectionCode]) groupsByKey[g.sectionCode] = []
        groupsByKey[g.sectionCode].push(g)
      })
      s.sections.lab = sections
      s.labGroupsByKey = groupsByKey
      s.labLoading = false
      if (!s.activeSection && sections.length) s.activeSection = sections[0].code
      s.buildGroups()
    }).catch((err) => {
      console.error('[lab_order_sheet_ui] crudGetAll failed:', err)
      s.labLoading = false
      s.sections.lab = []
      s.buildGroups()
    })
  }
  const loadSpecimenThenItems = (resolveSectionInfo) => {
    field.getFormRef().userState.crudGetAll({
      sdProvider: { providerId: '6a597657d448dfc9d33e2d3a', providerType: 'FORM', options: { limit: 200 } },
      totalEnable: true
    }, (specRes) => {
      const specimenRows = (specRes && specRes.data) || []
      const specimenByCode = {}
      specimenRows.forEach((sp) => {
        if (sp.code) specimenByCode[String(sp.code).trim().toUpperCase()] = sp
      })
      loadItems(resolveSectionInfo, makeSpecimenResolver(specimenByCode))
    }).catch((err) => {
      console.error('[lab_order_sheet_ui] specimen crudGetAll failed:', err)
      loadItems(resolveSectionInfo, makeSpecimenResolver({}))
    })
  }
  field.getFormRef().userState.crudGetAll({
    sdProvider: { providerId: '6a58f4dfd448dfc9d33e2bf2', providerType: 'FORM', options: { limit: 200 } },
    totalEnable: true
  }, (secRes) => {
    const sectionRows = (secRes && secRes.data) || []
    const sectionByRefCode = {}
    const sectionByCode = {}
    sectionRows.forEach((sec) => {
      if (sec.ref_code != null) sectionByRefCode[String(sec.ref_code)] = sec
      if (sec.code) sectionByCode[String(sec.code).toUpperCase()] = sec
    })
    loadSpecimenThenItems(makeSectionResolver(sectionByRefCode, sectionByCode))
  }).catch((err) => {
    console.error('[lab_order_sheet_ui] section crudGetAll failed:', err)
    loadSpecimenThenItems(makeSectionResolver({}, {}))
  })
}
