.trk-search .el-input__wrapper{border-radius:20px}
.trk-summary-mini{display:flex;gap:10px}
.trk-summary-item{display:flex;flex-direction:column;align-items:flex-end;padding:6px 16px;border-radius:10px;background:var(--el-fill-color-light);min-width:88px}
.trk-summary-label{font-size:11px;color:var(--el-text-color-secondary)}
.trk-summary-value{font-size:18px;font-weight:700;color:var(--el-text-color-primary);line-height:1.3}
.trk-summary-price{color:var(--el-color-primary)}
.trk-summary-unit{font-size:11px;color:var(--el-text-color-secondary)}

.trk-groups{column-width:260px;column-gap:20px}

.trk-group-card{border:1px solid var(--el-border-color-lighter);border-radius:12px;padding:12px 14px;background:var(--el-fill-color-blank);transition:border-color .15s ease,box-shadow .15s ease;break-inside:avoid;margin-bottom:16px;box-sizing:border-box}
.trk-group-card:hover{box-shadow:0 2px 10px rgba(0,0,0,.08)}
.trk-group-card.is-active{border-color:var(--el-color-primary-light-5)}
.trk-group-card.is-cross-section{border-color:var(--el-color-warning-light-5);background:var(--el-color-warning-light-9)}
.trk-cross-badge{font-size:11px;font-weight:600;color:var(--el-color-warning-dark-2);background:var(--el-color-warning-light-8);border-radius:999px;padding:1px 8px;flex:none}

.trk-group-head{display:flex;align-items:center;gap:8px;font-weight:700;padding-bottom:6px;margin-bottom:4px;border-bottom:1px dashed var(--el-border-color-lighter)}
.trk-group-name{cursor:pointer;flex:1}
.trk-group-badge{font-size:11px;font-weight:700;color:var(--el-color-primary);background:var(--el-color-primary-light-9);border-radius:999px;padding:1px 8px;flex:none}

.trk-item-row{display:flex;align-items:center;gap:8px;padding:5px 6px;margin-left:12px;font-size:13px;border-radius:6px;transition:background-color .12s ease;cursor:pointer}
.trk-item-row.is-checked{background:var(--el-color-primary-light-9)}
.trk-item-name{flex:1;cursor:pointer;color:var(--el-text-color-regular)}
.trk-item-row.is-checked .trk-item-name{color:var(--el-text-color-primary);font-weight:600}
.trk-item-price{color:var(--el-text-color-secondary);min-width:56px;text-align:right;font-variant-numeric:tabular-nums}
.trk-item-row.is-checked .trk-item-price{color:var(--el-color-primary);font-weight:600}

.trk-empty{column-span:all;display:flex;flex-direction:column;align-items:center;gap:8px;color:var(--el-text-color-placeholder);padding:36px 0}
.trk-empty-icon{width:36px;height:36px;opacity:.6}

.trk-footer{border:1px solid var(--el-border-color-lighter);border-radius:12px;padding:16px;background:var(--el-fill-color-light)}
.trk-footer-title{font-weight:700;margin-bottom:8px;font-size:15px}
.trk-footer-empty{color:var(--el-text-color-placeholder);font-size:13px}
.trk-footer-row{display:flex;justify-content:space-between;font-size:13px;padding:5px 0;color:var(--el-text-color-regular);border-bottom:1px solid var(--el-border-color-lighter)}
.trk-footer-row:last-child{border-bottom:none}
.trk-footer-row-label{font-weight:500}
.trk-footer-row-count{color:var(--el-color-primary);font-weight:600}
.trk-item-code{font-size:11px;font-weight:700;color:var(--el-color-primary);min-width:48px}
.trk-selected-row{display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--el-border-color-lighter)}
.trk-selected-code{min-width:64px;font-weight:700;color:var(--el-color-primary)}
.trk-selected-name{display:flex;flex:1;min-width:0;flex-direction:column}
.trk-selected-name small,.trk-selected-price small{font-size:11px;color:var(--el-text-color-secondary)}
.trk-selected-price{display:flex;min-width:105px;flex-direction:column;text-align:right;font-variant-numeric:tabular-nums}
.trk-remove{border:0;background:transparent;color:var(--el-color-danger);font-size:21px;cursor:pointer;padding:2px 6px}
.trk-selected-total{display:flex;justify-content:space-between;align-items:center;padding-top:12px;margin-top:4px;font-size:15px}
.trk-selected-total strong{font-size:18px;color:var(--el-color-primary)}

.trk-footer-head{display:flex;align-items:center;justify-content:space-between;gap:12px}
.trk-clear{border:0;background:transparent;color:var(--el-color-danger);font-weight:600;cursor:pointer;padding:4px 8px}

.trk-selected-card{border:1px solid var(--el-border-color-lighter);border-radius:10px;padding:10px 14px;margin-bottom:12px;background:var(--el-fill-color-blank)}
.trk-selected-card:last-child{margin-bottom:0}
.trk-selected-card-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding-bottom:6px;margin-bottom:2px;border-bottom:1px dashed var(--el-border-color-lighter)}
.trk-selected-card-title{font-weight:700;font-size:14px;color:var(--el-text-color-primary)}
.trk-selected-card-count{font-size:12px;font-weight:600;color:var(--el-color-primary);background:var(--el-color-primary-light-9);border-radius:999px;padding:1px 8px;flex:none}
.trk-selected-card .trk-selected-row:last-child{border-bottom:none}
.trk-selected-card-subtotal{display:flex;justify-content:flex-end;gap:6px;padding-top:6px;font-size:12px;color:var(--el-text-color-secondary)}
.trk-selected-card-subtotal strong{color:var(--el-text-color-regular);font-weight:600;font-size:13px}
.trk-hidden-field{display:none}
.trk-specimen-section-heading{font-weight:700;font-size:14px;color:var(--el-text-color-primary);margin-bottom:6px}
.trk-specimen-section-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));align-items:start;gap:10px;margin:2px 0 10px}
.trk-specimen-block{border:1px solid var(--el-border-color-lighter);border-radius:8px;padding:10px 12px;background:var(--el-fill-color-light)}
.trk-specimen-block-title{display:flex;align-items:center;justify-content:space-between;gap:8px;cursor:pointer;font-weight:700;font-size:16px;color:var(--el-color-success-dark-2);padding-bottom:8px;margin-bottom:8px;border-bottom:1px dashed var(--el-border-color-lighter)}
.trk-specimen-block.is-collapsed .trk-specimen-block-title{padding-bottom:0;margin-bottom:0;border-bottom:none}
.trk-specimen-fold-icon{flex:none;font-size:13px;color:var(--el-text-color-secondary)}
.trk-specimen-field-group{margin-bottom:14px}
.trk-specimen-field-group:last-child{margin-bottom:0}
.trk-specimen-label{display:block;font-weight:700;font-size:14px;color:var(--el-text-color-regular);margin-bottom:4px}
.trk-required{color:var(--el-color-danger)}
.trk-specimen-hint{font-size:11px;color:var(--el-text-color-secondary);margin-top:4px}

formConfig.onFormMounted:
const params = this.formParams || {};
if (params.visit_id) {
  this.setFieldValue('visit_id_link', String(params.visit_id));
}
if (params.hn) {
  this.setFieldValue('patient_hn', String(params.hn));
}
if (params.full_name) {
  this.setFieldValue('patient_name', String(params.full_name));
}
const photo = params.photo_url || (Array.isArray(params.p_pic) && params.p_pic[0] && params.p_pic[0].url) || '';
if (photo) {
  this.setFieldValue('patient_photo', String(photo));
}
if (Array.isArray(params.inscl_hos) && params.inscl_hos.length) {
  this.setFieldValue('inscl_hos_json', JSON.stringify(params.inscl_hos));
}
if (params.vn) {
  this.setFieldValue('visit_vn', String(params.vn));
}
if (params.visit_datetime) {
  this.setFieldValue('visit_time', String(params.visit_datetime));
}

formConfig.onFormDataChange:
const params = this.formParams || {};
console.log(params);

if (fieldName !== 'selected_items_json') return
const hasItems = newValue && newValue !== '[]' && newValue !== 'null'
if (hasItems) return
const widget = this.getFieldRef('order_sheet_ui')
if (widget && widget.vueState && widget.vueState.selected && Object.keys(widget.vueState.selected).length) {
  widget.vueState.selected = {}
  widget.vueState.gttMinutes = {}
  widget.vueState.customValues = {}
}
